or.script1:
function check() {
   var initiatorVal = workflowData.getMetaDataMap().get("Initiator");
   log.info("requestedBy :" + initiatorVal);
    if (initiatorVal == "ToRequestor"  || initiatorVal == "HRInitiates"  ) {
            return true;
    }
    else {
        return false;
    }
}

